// Generated by bench/gen_manycore.py --mesh 8x8 --core mcrv --l2-lines 64 --dir-ptrs 4
// 8x8 tiles (64 cores: mcrv), 4 rounds, work 32; expect checksum f4d66620
// SPDX-License-Identifier: Apache-2.0
// mc_router: 5-port mesh router for bench/gen_manycore.py (one per tile and network).
// Single-flit packets, dimension-ordered XY routing, a 2-deep input FIFO per
// port and round-robin arbitration per output. Ports: 0 local, 1 north (y-1),
// 2 east (x+1), 3 south (y+1), 4 west (x-1). The flit's top bits are the
// destination {x, y}. Ready towards a neighbour depends only on FIFO counts
// (registers), so mesh links have no combinational loops.
module mc_router #(parameter int XW = 1, YW = 1, FW = 32) (
  input  logic clk, rst_n,
  input  logic [XW-1:0] my_x,
  input  logic [YW-1:0] my_y,
  input  logic [4:0] in_v,
  input  logic [4:0][FW-1:0] in_f,
  output logic [4:0] in_rdy,
  output logic [4:0] out_v,
  output logic [4:0][FW-1:0] out_f,
  input  logic [4:0] out_rdy
);
  logic [4:0][1:0][FW-1:0] q;
  logic [4:0] hd;                 // head index per input FIFO
  logic [4:0][1:0] cnt;
  logic [4:0][2:0] want;          // output wanted by each input head
  logic [4:0][2:0] rr;            // last granted input per output
  logic [4:0][2:0] gnt;           // granted input per output
  logic [4:0] pop;

  always_comb begin
    for (int i = 0; i < 5; i++) begin
      logic [FW-1:0] h;
      logic [XW-1:0] dx;
      logic [YW-1:0] dy;
      h = q[i][hd[i]];
      dx = h[FW-1 -: XW];
      dy = h[FW-1-XW -: YW];
      if (dx > my_x) want[i] = 3'd2;
      else if (dx < my_x) want[i] = 3'd4;
      else if (dy > my_y) want[i] = 3'd3;
      else if (dy < my_y) want[i] = 3'd1;
      else want[i] = 3'd0;
      in_rdy[i] = cnt[i] != 2'd2;
    end
    pop = '0;
    for (int o = 0; o < 5; o++) begin
      out_v[o] = 1'b0;
      gnt[o] = 3'd0;
      for (int k = 1; k <= 5; k++) begin
        int i;
        i = (int'(rr[o]) + k) % 5;
        if (!out_v[o] && cnt[i] != 2'd0 && want[i] == 3'(o)) begin
          out_v[o] = 1'b1;
          gnt[o] = 3'(i);
        end
      end
      out_f[o] = q[gnt[o]][hd[gnt[o]]];
      if (out_v[o] && out_rdy[o]) pop[gnt[o]] = 1'b1;
    end
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      hd <= '0;
      cnt <= '0;
      rr <= '0;
    end else begin
      for (int i = 0; i < 5; i++) begin
        logic push;
        push = in_v[i] && in_rdy[i];
        if (push) q[i][hd[i] ^ (cnt[i] == 2'd1 || (cnt[i] == 2'd2))] <= in_f[i];
        if (pop[i]) hd[i] <= ~hd[i];
        cnt[i] <= cnt[i] + 2'(push) - 2'(pop[i]);
      end
      for (int o = 0; o < 5; o++)
        if (out_v[o] && out_rdy[o]) rr[o] <= gnt[o];
    end
  end
endmodule

// SPDX-License-Identifier: Apache-2.0
// mc_l1: private L1 data cache of one tile (bench/gen_manycore.py).
// Direct-mapped, 16-byte lines, write-through and no-write-allocate, like the
// L1/L1.5 pair of a tiled many-core: reads hit locally, misses fetch the line
// from its home L2 slice over NoC1 and fill from NoC2; writes update a hit
// line and always go to the home slice, which invalidates the other sharers
// before it acknowledges. One request is outstanding per core, so the home
// slices serialise every location and the program sees sequential
// consistency. Invalidations arrive on NoC2 and are acknowledged on NoC3.
//
// Flit (MSB first): dst x | dst y | src {y, x} | type(3) | addr(28) | wstrb(4) | data(128)
module mc_l1 #(parameter int XW = 1, YW = 1, X = 1, Y = 1, SETS = 16) (
  input  logic clk, rst_n,
  input  logic [XW-1:0] my_x,
  input  logic [YW-1:0] my_y,
  // core side: shared (amo=0) or fetch-and-increment (amo=1) access
  input  logic        c_valid,
  input  logic        c_amo,
  input  logic [27:0] c_addr,
  input  logic [31:0] c_wdata,
  input  logic [3:0]  c_wstrb,
  output logic        c_ready,
  output logic [31:0] c_rdata,
  // NoC1 inject (requests), NoC2 eject (data, acks, invalidations), NoC3 inject (inv acks)
  output logic n1_v, input logic n1_rdy, output logic [XW+YW+XW+YW+3+28+4+128-1:0] n1_f,
  input  logic n2_v, output logic n2_rdy, input logic [XW+YW+XW+YW+3+28+4+128-1:0] n2_f,
  output logic n3_v, input logic n3_rdy, output logic [XW+YW+XW+YW+3+28+4+128-1:0] n3_f
);
  localparam int IW = XW + YW;
  localparam int FW = IW + IW + 3 + 28 + 4 + 128;
  localparam int N = X * Y;
  localparam int SB = $clog2(SETS);
  localparam logic [2:0] T_RD = 3'd1, T_WR = 3'd2, T_AMO = 3'd3, T_DATA = 3'd4, T_WACK = 3'd5,
                         T_INV = 3'd6, T_IACK = 3'd7;

  logic [127:0] data [SETS];
  logic [23-SB:0] tag [SETS];
  logic [SETS-1:0] valid;

  typedef enum logic {IDLE, WAIT} st_t;
  st_t st;
  logic [27:0] a;                  // latched request address

  wire [23:0] c_line = c_addr[27:4];
  wire [SB-1:0] c_set = c_line[SB-1:0];
  wire c_hit = valid[c_set] && tag[c_set] == c_line[23:SB];
  wire [31:0] c_word = data[c_set][c_addr[3:2]*32 +: 32];

  // home tile of a line: line mod N, then {x, y}
  function automatic logic [IW-1:0] home_xy(input logic [23:0] line);
    int h;
    logic [XW-1:0] hx;
    logic [YW-1:0] hy;
    h = int'(line % 24'(N));
    hx = XW'(h % X);
    hy = YW'(h / X);
    return {hx, hy};
  endfunction

  wire [2:0] n2_t = n2_f[FW-1-IW-IW -: 3];
  wire [27:0] n2_a = n2_f[FW-1-IW-IW-3 -: 28];
  wire [IW-1:0] n2_src = n2_f[FW-1-IW -: IW];   // {x, y}
  wire [23:0] n2_line = n2_a[27:4];
  wire [SB-1:0] n2_set = n2_line[SB-1:0];

  assign n2_rdy = !n3_v;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      st <= IDLE;
      valid <= '0;
      n1_v <= 1'b0;
      n3_v <= 1'b0;
      c_ready <= 1'b0;
    end else begin
      c_ready <= 1'b0;
      if (n1_v && n1_rdy) n1_v <= 1'b0;
      if (n3_v && n3_rdy) n3_v <= 1'b0;
      case (st)
        IDLE: if (c_valid && !c_ready) begin
          a <= c_addr;
          if (!c_amo && c_wstrb == 4'd0 && c_hit) begin
            c_rdata <= c_word;
            c_ready <= 1'b1;
          end else begin
            n1_v <= 1'b1;
            n1_f <= {home_xy(c_line), my_x, my_y,
                     c_amo ? T_AMO : (c_wstrb == 4'd0 ? T_RD : T_WR),
                     c_addr, c_wstrb, 96'd0, c_wdata};
            st <= WAIT;
            if (c_amo) valid[c_set] <= 1'b0;
            else if (c_wstrb != 4'd0 && c_hit)
              for (int b = 0; b < 4; b++)
                if (c_wstrb[b]) data[c_set][c_addr[3:2]*32 + b*8 +: 8] <= c_wdata[b*8 +: 8];
          end
        end
        default: ;
      endcase
      if (n2_v && n2_rdy) begin
        case (n2_t)
          T_DATA: begin
            data[n2_set] <= n2_f[127:0];
            tag[n2_set] <= n2_line[23:SB];
            valid[n2_set] <= 1'b1;
            c_rdata <= n2_f[a[3:2]*32 +: 32];
            c_ready <= 1'b1;
            st <= IDLE;
          end
          T_WACK: begin
            c_rdata <= n2_f[31:0];
            c_ready <= 1'b1;
            st <= IDLE;
          end
          T_INV: begin
            if (valid[n2_set] && tag[n2_set] == n2_line[23:SB]) valid[n2_set] <= 1'b0;
            n3_v <= 1'b1;
            n3_f <= {n2_src, my_x, my_y, T_IACK, n2_a, 4'd0, 128'd0};
          end
          default: ;
        endcase
      end
    end
  end
endmodule

// SPDX-License-Identifier: Apache-2.0
// mc_l2: one slice of the distributed shared L2 / memory (bench/gen_manycore.py).
// Lines are interleaved over the tiles (home = line mod N); this slice holds
// LINES lines and a directory entry per line. The directory is limited-pointer
// with broadcast on overflow (Dir_PTRS_B): up to PTRS sharer tiles are kept,
// a further sharer sets the overflow bit and the next write invalidates every
// tile. The slice handles one request at a time:
//   RD  -> add the requester as a sharer, send the line (DATA)
//   WR  -> merge the word, invalidate the other sharers, wait for their acks, WACK;
//          the writer is then the only sharer (its write-through copy is current)
//   AMO -> fetch-and-increment the word, invalidate, wait, WACK with the old value
// NoC1 carries requests in, NoC2 carries data/acks/invalidations out, NoC3
// brings invalidation acks back and is always drained, so the three networks
// cannot deadlock each other.
module mc_l2 #(parameter int XW = 1, YW = 1, X = 1, Y = 1, LINES = 64, PTRS = 4) (
  input  logic clk, rst_n,
  input  logic [XW-1:0] my_x,
  input  logic [YW-1:0] my_y,
  input  logic n1_v, output logic n1_rdy, input logic [XW+YW+XW+YW+3+28+4+128-1:0] n1_f,
  output logic n2_v, input logic n2_rdy, output logic [XW+YW+XW+YW+3+28+4+128-1:0] n2_f,
  input  logic n3_v, output logic n3_rdy, input logic [XW+YW+XW+YW+3+28+4+128-1:0] n3_f,
  output logic [31:0] n_req                 // requests served (statistics)
);
  localparam int IW = XW + YW;
  localparam int FW = IW + IW + 3 + 28 + 4 + 128;
  localparam int N = X * Y;
  localparam int LB = $clog2(LINES);
  localparam int PB = $clog2(PTRS + 1);
  localparam logic [2:0] T_RD = 3'd1, T_WR = 3'd2, T_AMO = 3'd3, T_DATA = 3'd4, T_WACK = 3'd5,
                         T_INV = 3'd6;

  logic [127:0] mem [LINES];
  logic [PTRS-1:0][IW-1:0] ptr [LINES];
  logic [PB-1:0] cnt [LINES];
  logic [LINES-1:0] ovf;

  typedef enum logic [1:0] {IDLE, INV, ACK, RESP} st_t;
  st_t st;
  logic [IW-1:0] src;
  logic [2:0] typ;
  logic [27:0] a;
  logic [31:0] old;
  logic [PTRS-1:0][IW-1:0] tp;     // invalidation targets (pointer mode)
  logic [PB-1:0] tn;
  logic bcast;
  logic [31:0] it;                 // target iterator
  logic [XW-1:0] bx;
  logic [YW-1:0] by;
  logic [31:0] sent, acks;

  wire [IW-1:0] f_src = n1_f[FW-1-IW -: IW];
  wire [2:0] f_t = n1_f[FW-1-IW-IW -: 3];
  wire [27:0] f_a = n1_f[FW-1-IW-IW-3 -: 28];
  wire [3:0] f_be = n1_f[131:128];
  wire [31:0] f_d = n1_f[31:0];
  wire [23:0] f_line = f_a[27:4];
  wire [LB-1:0] f_idx = LB'(f_line / 24'(N));
  wire [LB-1:0] a_idx = LB'(a[27:4] / 24'(N));
  wire [31:0] f_word = mem[f_idx][f_a[3:2]*32 +: 32];

  assign n1_rdy = st == IDLE && !n2_v;
  assign n3_rdy = 1'b1;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      st <= IDLE;
      n2_v <= 1'b0;
      ovf <= '0;
      acks <= '0;
      n_req <= '0;
      for (int l = 0; l < LINES; l++) begin
        cnt[l] <= '0;
        mem[l] <= '0;
      end
    end else begin
      if (n2_v && n2_rdy) n2_v <= 1'b0;
      if (n3_v) acks <= acks + 1;
      case (st)
        IDLE: if (n1_v && n1_rdy) begin
          n_req <= n_req + 1;
          src <= f_src;
          typ <= f_t;
          a <= f_a;
          old <= f_word;
          if (f_t == T_RD) begin
            if (!ovf[f_idx]) begin
              logic dup;
              dup = 1'b0;
              for (int p = 0; p < PTRS; p++)
                if (PB'(p) < cnt[f_idx] && ptr[f_idx][p] == f_src) dup = 1'b1;
              if (!dup) begin
                if (cnt[f_idx] == PB'(PTRS)) ovf[f_idx] <= 1'b1;
                else begin
                  ptr[f_idx][cnt[f_idx]] <= f_src;
                  cnt[f_idx] <= cnt[f_idx] + 1'b1;
                end
              end
            end
            n2_v <= 1'b1;
            n2_f <= {f_src, my_x, my_y, T_DATA, f_a, 4'd0, mem[f_idx]};
          end else begin
            if (f_t == T_AMO) mem[f_idx][f_a[3:2]*32 +: 32] <= f_word + 32'd1;
            else
              for (int b = 0; b < 4; b++)
                if (f_be[b]) mem[f_idx][f_a[3:2]*32 + b*8 +: 8] <= f_d[b*8 +: 8];
            tp <= ptr[f_idx];
            tn <= cnt[f_idx];
            bcast <= ovf[f_idx];
            // the writer keeps its (updated) copy, so it stays the one sharer;
            // an AMO requester dropped its copy when it sent the request
            if (f_t == T_WR) begin
              ptr[f_idx][0] <= f_src;
              cnt[f_idx] <= PB'(1);
            end else cnt[f_idx] <= '0;
            ovf[f_idx] <= 1'b0;
            it <= '0;
            bx <= '0;
            by <= '0;
            sent <= '0;
            acks <= n3_v ? 32'd1 : 32'd0;   // stale acks cannot exist: count from here
            st <= INV;
          end
        end
        INV: if (!n2_v || n2_rdy) begin
          // send at most one invalidation per cycle
          logic go, last;
          logic [IW-1:0] t;
          go = 1'b0;
          last = 1'b0;
          if (bcast) begin
            t = {bx, by};
            go = t != src;
            last = int'(bx) == X - 1 && int'(by) == Y - 1;
            if (int'(bx) == X - 1) begin
              bx <= '0;
              by <= by + 1'b1;
            end else bx <= bx + 1'b1;
          end else begin
            last = it + 1 >= 32'(tn);
            if (it < 32'(tn)) begin
              t = tp[it[$clog2(PTRS+1)-1:0]];
              go = t != src;
            end else t = '0;
            it <= it + 1;
          end
          n2_v <= go;
          if (go) begin
            n2_f <= {t, my_x, my_y, T_INV, a, 4'd0, 128'd0};
            sent <= sent + 1;
          end
          if (last) st <= ACK;
        end
        ACK: if (acks == sent && (!n2_v || n2_rdy)) begin
          n2_v <= 1'b1;
          n2_f <= {src, my_x, my_y, T_WACK, a, 4'd0, 96'd0, old};
          st <= RESP;
        end
        RESP: if (!n2_v || n2_rdy) st <= IDLE;
        default: ;
      endcase
    end
  end
endmodule

// SPDX-License-Identifier: Apache-2.0
// mc_rv: a small multi-cycle RV32I core written for bench/gen_manycore.py,
// so the many-core needs no outside sources (--core mcrv). It implements all
// of RV32I except FENCE/ECALL/EBREAK/CSR (executed as no-ops) and talks to
// the tile through the same held-request port as the other cores: valid
// stays high until a one-cycle ready, read data comes with ready.
// Fetch, execute, and for loads/stores one memory access: 2 cycles plus
// memory latency per instruction, similar to PicoRV32.
module mc_rv (
  input  logic clk, rst_n,
  output logic req_valid,
  output logic [31:0] req_addr, req_wdata,
  output logic [3:0] req_wstrb,
  input  logic req_ready,
  input  logic [31:0] rdata
);
  typedef enum logic [1:0] {FETCH, EXEC, MEM} st_t;
  st_t st;
  logic [31:0] pc, ir;
  logic [31:0] x [32];

  wire [6:0] op = ir[6:0];
  wire [4:0] rd = ir[11:7], rs1 = ir[19:15], rs2 = ir[24:20];
  wire [2:0] f3 = ir[14:12];
  wire [31:0] a = rs1 == 5'd0 ? 32'd0 : x[rs1];
  wire [31:0] b = rs2 == 5'd0 ? 32'd0 : x[rs2];
  wire [31:0] imm_i = {{20{ir[31]}}, ir[31:20]};
  wire [31:0] imm_s = {{20{ir[31]}}, ir[31:25], ir[11:7]};
  wire [31:0] imm_b = {{19{ir[31]}}, ir[31], ir[7], ir[30:25], ir[11:8], 1'b0};
  wire [31:0] imm_u = {ir[31:12], 12'd0};
  wire [31:0] imm_j = {{11{ir[31]}}, ir[31], ir[19:12], ir[20], ir[30:21], 1'b0};
  wire [31:0] ea = a + (op == 7'h23 ? imm_s : imm_i);

  function automatic logic [31:0] alu(input logic [2:0] f, input logic alt, input logic [31:0] p, q);
    case (f)
      3'd0: return alt ? p - q : p + q;
      3'd1: return p << q[4:0];
      3'd2: return {31'd0, $signed(p) < $signed(q)};
      3'd3: return {31'd0, p < q};
      3'd4: return p ^ q;
      3'd5: return alt ? 32'($signed(p) >>> q[4:0]) : p >> q[4:0];
      3'd6: return p | q;
      default: return p & q;
    endcase
  endfunction

  logic take;
  always_comb
    case (f3)
      3'd0: take = a == b;
      3'd1: take = a != b;
      3'd4: take = $signed(a) < $signed(b);
      3'd5: take = $signed(a) >= $signed(b);
      3'd6: take = a < b;
      3'd7: take = a >= b;
      default: take = 1'b0;
    endcase

  // load data: pick and extend the addressed byte/half
  logic [31:0] ld;
  always_comb begin
    logic [31:0] sh;
    sh = rdata >> (8 * req_addr[1:0]);
    case (f3)
      3'd0: ld = {{24{sh[7]}}, sh[7:0]};
      3'd1: ld = {{16{sh[15]}}, sh[15:0]};
      3'd4: ld = {24'd0, sh[7:0]};
      3'd5: ld = {16'd0, sh[15:0]};
      default: ld = rdata;
    endcase
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      st <= FETCH;
      pc <= 32'd0;
      req_valid <= 1'b0;
      for (int r = 0; r < 32; r++) x[r] <= 32'd0;
    end else begin
      case (st)
        FETCH: begin
          if (!req_valid) begin
            req_valid <= 1'b1;
            req_addr <= pc;
            req_wstrb <= 4'd0;
          end else if (req_ready) begin
            req_valid <= 1'b0;
            ir <= rdata;
            st <= EXEC;
          end
        end
        EXEC: begin
          logic [31:0] res;
          logic wb;
          res = 32'd0;
          wb = 1'b1;
          pc <= pc + 4;
          st <= FETCH;
          case (op)
            7'h37: res = imm_u;                                   // LUI
            7'h17: res = pc + imm_u;                              // AUIPC
            7'h6f: begin res = pc + 4; pc <= pc + imm_j; end      // JAL
            7'h67: begin res = pc + 4; pc <= (a + imm_i) & ~32'd1; end   // JALR
            7'h63: begin wb = 1'b0; if (take) pc <= pc + imm_b; end      // branches
            7'h13: res = alu(f3, f3 == 3'd5 && ir[30], a, f3 == 3'd1 || f3 == 3'd5 ? {27'd0, ir[24:20]} : imm_i);
            7'h33: res = alu(f3, ir[30], a, b);
            7'h03, 7'h23: begin                                  // loads, stores
              wb = 1'b0;
              req_valid <= 1'b1;
              req_addr <= ea;
              req_wdata <= b << (8 * ea[1:0]);
              req_wstrb <= op == 7'h03 ? 4'd0 :
                           f3[1:0] == 2'd0 ? 4'b0001 << ea[1:0] :
                           f3[1:0] == 2'd1 ? 4'b0011 << ea[1:0] : 4'b1111;
              st <= MEM;
            end
            default: wb = 1'b0;                                   // FENCE, SYSTEM: no-ops
          endcase
          if (wb && rd != 5'd0) x[rd] <= res;
        end
        default: begin                                            // MEM
          if (req_ready) begin
            req_valid <= 1'b0;
            if (op == 7'h03 && rd != 5'd0) x[rd] <= ld;
            st <= FETCH;
          end
        end
      endcase
    end
  end
endmodule

// SPDX-License-Identifier: Apache-2.0
// mc_tile: one tile of the bench/gen_manycore.py many-core: a RISC-V core,
// 4 KB of private RAM holding the program (the same image in every tile),
// a few memory-mapped registers, the private L1 data cache, this tile's slice
// of the shared L2 with its directory, and one router per network (NoC1
// requests, NoC2 responses and invalidations, NoC3 invalidation acks).
// Tile coordinates come in on ports, as chip straps would, so every tile of a
// core type is the same module with the same parameters.
//
// Core address map:
//   0x0000_0000-0x0000_0FFF  private RAM (code and per-core constants)
//   0x8000_0000-0x8FFF_FFFF  shared memory, cached in L1, homed by line
//   0xC000_0000-0xCFFF_FFFF  same locations; a load is fetch-and-increment
//   0xF000_0000              write: done flag     0xF000_0004 write: result
//   0xF000_0008              read: linear tile id 0xF000_000C read: cycle count
//
// Mesh ports: index [net][dir], net 0..2 = NoC1..3, dir 0 N, 1 E, 2 S, 3 W.
module mc_tile #(parameter int XW = 1, YW = 1, X = 1, Y = 1, CORE = 0, L2_LINES = 64,
                 L1_SETS = 16, DIR_PTRS = 4) (
  input  logic clk, rst_n,
  input  logic [XW-1:0] my_x,
  input  logic [YW-1:0] my_y,
  input  logic [31:0] my_id,
  input  logic [2:0][3:0] in_v,
  input  logic [2:0][3:0][XW+YW+XW+YW+3+28+4+128-1:0] in_f,
  output logic [2:0][3:0] in_rdy,
  output logic [2:0][3:0] out_v,
  output logic [2:0][3:0][XW+YW+XW+YW+3+28+4+128-1:0] out_f,
  input  logic [2:0][3:0] out_rdy,
  output logic done,
  output logic [31:0] result,
  output logic [31:0] n_l2req
);
  localparam int FW = XW + YW + XW + YW + 3 + 28 + 4 + 128;

  // ---- core, normalised to a held request: valid until a one-cycle ready ----
  logic        req_valid, req_ready;
  logic [31:0] req_addr, req_wdata, rdata;
  logic [3:0]  req_wstrb;
  mc_core #(.CORE(CORE)) core(.clk(clk), .rst_n(rst_n), .req_valid(req_valid), .req_addr(req_addr),
    .req_wdata(req_wdata), .req_wstrb(req_wstrb), .req_ready(req_ready), .rdata(rdata));

  // ---- private RAM and registers ----
  logic [31:0] ram [1024];
  initial begin
    for (int k = 0; k < 1024; k++) ram[k] = 32'd0;
    ram[0] = 32'h41402683;
    ram[1] = 32'h0086a203;
    ram[2] = 32'h40002283;
    ram[3] = 32'h40c02483;
    ram[4] = 32'h00221513;
    ram[5] = 32'h00120593;
    ram[6] = 32'h00559463;
    ram[7] = 32'h00000593;
    ram[8] = 32'h40402103;
    ram[9] = 32'h00220633;
    ram[10] = 32'h00566463;
    ram[11] = 32'h40560633;
    ram[12] = 32'h00259593;
    ram[13] = 32'h00261613;
    ram[14] = 32'h41802103;
    ram[15] = 32'h00120093;
    ram[16] = 32'h0020c0b3;
    ram[17] = 32'h00000313;
    ram[18] = 32'h41c02783;
    ram[19] = 32'h00000413;
    ram[20] = 32'h40802383;
    ram[21] = 32'h00f27193;
    ram[22] = 32'h00319193;
    ram[23] = 32'h42802103;
    ram[24] = 32'h002181b3;
    ram[25] = 32'h00d09113;
    ram[26] = 32'h0020c0b3;
    ram[27] = 32'h0110d113;
    ram[28] = 32'h0020c0b3;
    ram[29] = 32'h00509113;
    ram[30] = 32'h0020c0b3;
    ram[31] = 32'hfff18193;
    ram[32] = 32'hfe0192e3;
    ram[33] = 32'h42002683;
    ram[34] = 32'h009686b3;
    ram[35] = 32'h006686b3;
    ram[36] = 32'h00a68733;
    ram[37] = 32'h00172023;
    ram[38] = 32'h00540433;
    ram[39] = 32'h41002103;
    ram[40] = 32'h00012703;
    ram[41] = 32'h00170713;
    ram[42] = 32'h00871463;
    ram[43] = 32'h0084a823;
    ram[44] = 32'h0104a703;
    ram[45] = 32'hfe876ee3;
    ram[46] = 32'h00b68733;
    ram[47] = 32'h00072103;
    ram[48] = 32'h00c68733;
    ram[49] = 32'h00072703;
    ram[50] = 32'h00e14133;
    ram[51] = 32'h002080b3;
    ram[52] = 32'h00f34333;
    ram[53] = 32'hfff38393;
    ram[54] = 32'hf6039ee3;
    ram[55] = 32'h42402683;
    ram[56] = 32'h009686b3;
    ram[57] = 32'h00a68733;
    ram[58] = 32'h00172023;
    ram[59] = 32'h00540433;
    ram[60] = 32'h41002103;
    ram[61] = 32'h00012703;
    ram[62] = 32'h00170713;
    ram[63] = 32'h00871463;
    ram[64] = 32'h0084a823;
    ram[65] = 32'h0104a703;
    ram[66] = 32'hfe876ee3;
    ram[67] = 32'h02021c63;
    ram[68] = 32'h00000113;
    ram[69] = 32'h00028193;
    ram[70] = 32'h00068713;
    ram[71] = 32'h00072083;
    ram[72] = 32'h00111313;
    ram[73] = 32'h01f15393;
    ram[74] = 32'h00736133;
    ram[75] = 32'h00114133;
    ram[76] = 32'h00470713;
    ram[77] = 32'hfff18193;
    ram[78] = 32'hfe0192e3;
    ram[79] = 32'h41402683;
    ram[80] = 32'h0026a223;
    ram[81] = 32'h41402683;
    ram[82] = 32'h00100113;
    ram[83] = 32'h0026a023;
    ram[84] = 32'h0000006f;
    ram[256] = 32'h00000040;
    ram[257] = 32'h00000008;
    ram[258] = 32'h00000004;
    ram[259] = 32'h80000000;
    ram[260] = 32'hc0000000;
    ram[261] = 32'hf0000000;
    ram[262] = 32'h9e3779b9;
    ram[263] = 32'h00000100;
    ram[264] = 32'h00000040;
    ram[265] = 32'h00000240;
    ram[266] = 32'h00000020;
  end
  logic loc_ready;
  logic [31:0] loc_rdata, cycles;
  wire is_priv = req_addr[31:28] == 4'h0;
  wire is_mmio = req_addr[31:28] == 4'hF;
  wire is_shr  = req_addr[31:28] == 4'h8 || req_addr[31:28] == 4'hC;
  // plain always: ram also has an initial block with the program image
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      loc_ready <= 1'b0;
      done <= 1'b0;
      result <= '0;
      cycles <= '0;
    end else begin
      cycles <= cycles + 1;
      loc_ready <= 1'b0;
      if (req_valid && !req_ready && !is_shr) begin
        loc_ready <= 1'b1;
        if (is_priv) begin
          loc_rdata <= ram[req_addr[11:2]];
          for (int b = 0; b < 4; b++)
            if (req_wstrb[b]) ram[req_addr[11:2]][b*8 +: 8] <= req_wdata[b*8 +: 8];
        end else begin
          loc_rdata <= req_addr[3:2] == 2'd2 ? my_id : req_addr[3:2] == 2'd3 ? cycles : 32'd0;
          if (req_wstrb != 4'd0 && req_addr[3:2] == 2'd0) done <= req_wdata[0];
          if (req_wstrb != 4'd0 && req_addr[3:2] == 2'd1) result <= req_wdata;
        end
      end
    end
  end

  // ---- L1 ----
  logic l1_ready;
  logic [31:0] l1_rdata;
  logic [2:0] lv, lr;               // local port valid/ready per network, router -> tile
  logic [2:0] tv, tr;               // tile -> router
  logic [2:0][FW-1:0] lf, tf;
  mc_l1 #(.XW(XW), .YW(YW), .X(X), .Y(Y), .SETS(L1_SETS)) l1(.clk(clk), .rst_n(rst_n),
    .my_x(my_x), .my_y(my_y),
    .c_valid(req_valid && is_shr && !req_ready), .c_amo(req_addr[30]), .c_addr(req_addr[27:0]),
    .c_wdata(req_wdata), .c_wstrb(req_wstrb), .c_ready(l1_ready), .c_rdata(l1_rdata),
    .n1_v(tv[0]), .n1_rdy(tr[0]), .n1_f(tf[0]),
    .n2_v(lv[1]), .n2_rdy(lr[1]), .n2_f(lf[1]),
    .n3_v(tv[2]), .n3_rdy(tr[2]), .n3_f(tf[2]));
  assign req_ready = loc_ready | l1_ready;
`ifdef MC_TRACE
  // +define+MC_TRACE: one line per completed core access
  always @(posedge clk)
    if (req_valid && req_ready)
      $display("%0t tile %0d %s %h %h", $time, my_id, req_wstrb != 4'd0 ? "W" : "R", req_addr,
               req_wstrb != 4'd0 ? req_wdata : rdata);
`endif
  assign rdata = loc_ready ? loc_rdata : l1_rdata;

  // ---- L2 slice ----
  mc_l2 #(.XW(XW), .YW(YW), .X(X), .Y(Y), .LINES(L2_LINES), .PTRS(DIR_PTRS)) l2(.clk(clk), .rst_n(rst_n),
    .my_x(my_x), .my_y(my_y),
    .n1_v(lv[0]), .n1_rdy(lr[0]), .n1_f(lf[0]),
    .n2_v(tv[1]), .n2_rdy(tr[1]), .n2_f(tf[1]),
    .n3_v(lv[2]), .n3_rdy(lr[2]), .n3_f(lf[2]),
    .n_req(n_l2req));

  // ---- routers: port 0 local, 1..4 = N E S W ----
  for (genvar n = 0; n < 3; n++) begin : net
    logic [4:0] iv, ir, ov, orr;
    logic [4:0][FW-1:0] ifl, ofl;
    assign iv = {in_v[n], tv[n]};
    assign ifl = {in_f[n], tf[n]};
    assign {in_rdy[n], tr[n]} = ir;
    assign {out_v[n], lv[n]} = ov;
    assign {out_f[n], lf[n]} = ofl;
    assign orr = {out_rdy[n], lr[n]};
    mc_router #(.XW(XW), .YW(YW), .FW(FW)) r(.clk(clk), .rst_n(rst_n), .my_x(my_x), .my_y(my_y),
      .in_v(iv), .in_f(ifl), .in_rdy(ir), .out_v(ov), .out_f(ofl), .out_rdy(orr));
  end
endmodule

// mc_core: the tile's RISC-V core behind one held-request memory port
// (valid stays high until the one-cycle ready; read data comes with ready).
module mc_core #(parameter int CORE = 0) (
  input  logic clk, rst_n,
  output logic req_valid,
  output logic [31:0] req_addr, req_wdata,
  output logic [3:0] req_wstrb,
  input  logic req_ready,
  input  logic [31:0] rdata
);
  generate
    if (CORE == 2) begin : g_mcrv
      mc_rv cpu(.clk(clk), .rst_n(rst_n), .req_valid(req_valid), .req_addr(req_addr), .req_wdata(req_wdata),
                .req_wstrb(req_wstrb), .req_ready(req_ready), .rdata(rdata));
    end
  endgenerate
endmodule

module mc_soc (input logic clk, rst_n, output logic [63:0] done, output logic [31:0] result,
               output logic [31:0] l2req [64]);
  localparam int X = 8, Y = 8, XW = 3, YW = 3;
  localparam int FW = XW + YW + XW + YW + 3 + 28 + 4 + 128;
  // per tile and network: valid/flit/ready leaving through each side (0 N, 1 E, 2 S, 3 W)
  wire [2:0][3:0] ov [Y][X], iv [Y][X], ordy [Y][X], irdy [Y][X];
  wire [2:0][3:0][FW-1:0] of [Y][X], ifl [Y][X];
  wire [31:0] res [Y][X];
  function automatic int CORE_OF(int i); return 2; endfunction
  for (genvar ty = 0; ty < Y; ty++) begin : row
    for (genvar tx = 0; tx < X; tx++) begin : col
      for (genvar n = 0; n < 3; n++) begin : link
        // north side <- south side of (tx, ty-1), and so on; mesh edges are tied off
        assign iv[ty][tx][n][0]  = ty > 0     ? ov[ty > 0 ? ty-1 : 0][tx][n][2] : 1'b0;
        assign ifl[ty][tx][n][0] = ty > 0     ? of[ty > 0 ? ty-1 : 0][tx][n][2] : '0;
        assign ordy[ty][tx][n][0] = ty > 0    ? irdy[ty > 0 ? ty-1 : 0][tx][n][2] : 1'b1;
        assign iv[ty][tx][n][2]  = ty < Y - 1 ? ov[ty < Y-1 ? ty+1 : ty][tx][n][0] : 1'b0;
        assign ifl[ty][tx][n][2] = ty < Y - 1 ? of[ty < Y-1 ? ty+1 : ty][tx][n][0] : '0;
        assign ordy[ty][tx][n][2] = ty < Y - 1 ? irdy[ty < Y-1 ? ty+1 : ty][tx][n][0] : 1'b1;
        assign iv[ty][tx][n][1]  = tx < X - 1 ? ov[ty][tx < X-1 ? tx+1 : tx][n][3] : 1'b0;
        assign ifl[ty][tx][n][1] = tx < X - 1 ? of[ty][tx < X-1 ? tx+1 : tx][n][3] : '0;
        assign ordy[ty][tx][n][1] = tx < X - 1 ? irdy[ty][tx < X-1 ? tx+1 : tx][n][3] : 1'b1;
        assign iv[ty][tx][n][3]  = tx > 0     ? ov[ty][tx > 0 ? tx-1 : 0][n][1] : 1'b0;
        assign ifl[ty][tx][n][3] = tx > 0     ? of[ty][tx > 0 ? tx-1 : 0][n][1] : '0;
        assign ordy[ty][tx][n][3] = tx > 0    ? irdy[ty][tx > 0 ? tx-1 : 0][n][1] : 1'b1;
      end
      mc_tile #(.XW(XW), .YW(YW), .X(X), .Y(Y), .CORE(CORE_OF(ty * X + tx)),
                .L2_LINES(64), .DIR_PTRS(4)) t (
        .clk(clk), .rst_n(rst_n), .my_x(XW'(tx)), .my_y(YW'(ty)), .my_id(32'(ty * X + tx)),
        .in_v(iv[ty][tx]), .in_f(ifl[ty][tx]), .in_rdy(irdy[ty][tx]),
        .out_v(ov[ty][tx]), .out_f(of[ty][tx]), .out_rdy(ordy[ty][tx]),
        .done(done[ty * X + tx]), .result(res[ty][tx]), .n_l2req(l2req[ty * X + tx]));
    end
  end
  assign result = res[0][0];
endmodule

module mc_tb;
  logic clk = 1'b0, rst_n = 1'b0;
  logic [63:0] done;
  logic [31:0] result;
  logic [31:0] l2req [64];
  mc_soc soc(.clk(clk), .rst_n(rst_n), .done(done), .result(result), .l2req(l2req));
  always #5 clk = ~clk;
  initial begin
    longint cyc;
    longint reqs;
    int nd;
    #20 rst_n = 1'b1;
    cyc = 0;
    while (!(&done) && cyc < 77392) begin
      @(posedge clk);
      cyc++;
    end
    nd = 0;
    reqs = 0;
    for (int i = 0; i < 64; i++) begin
      if (done[i]) nd++;
      reqs += l2req[i];
    end
    $display("mc: tiles=64 mesh=8x8 cores=mcrv done=%0d/64 cycles=%0d l2_requests=%0d checksum=%h expect=f4d66620 %s",
             nd, cyc, reqs, result, (done[0] && result == 32'hf4d66620) ? "PASS" : "FAIL");
    $finish;
  end
endmodule
